package com.example.indoorar

import android.content.Intent
import android.os.Bundle
import com.google.android.material.bottomnavigation.BottomNavigationView

class ActivityFavoritos : BaseActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_favoritos)

        // Wire bottom navigation (conta comum)
        findViewById<BottomNavigationView>(R.id.bottomNavComum)?.apply {
            // mark favoritos as selected
            selectedItemId = R.id.action_favoritos
            setOnItemSelectedListener { item ->
                if (this.selectedItemId == item.itemId) return@setOnItemSelectedListener true
                when (item.itemId) {
                    R.id.action_home -> { startActivity(Intent(this@ActivityFavoritos, ActivityHomeComum::class.java)); true }
                    R.id.action_scan -> { startActivity(Intent(this@ActivityFavoritos, ActivityScanQR::class.java)); true }
                    R.id.action_favoritos -> { true }
                    R.id.action_config -> { startActivity(Intent(this@ActivityFavoritos, ActivityPerfilComum::class.java)); true }
                    else -> false
                }
            }
        }
    }
}

package com.example.indoorar

import android.content.Intent
import android.os.Bundle
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import com.google.android.material.bottomnavigation.BottomNavigationView

class ActivityFavoritos : BaseActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_favoritos)

        // Aplicar insets no root: somente topo/laterais
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, 0)
            insets
        }

        // Bottom navigation (conta comum)
        findViewById<BottomNavigationView>(R.id.bottomNavComum)?.apply {
            // Evita padding inferior por insets para manter colada no fundo
            ViewCompat.setOnApplyWindowInsetsListener(this) { v, insets ->
                v.setPadding(v.paddingLeft, v.paddingTop, v.paddingRight, 0)
                insets
            }

            // mark favoritos as selected
            selectedItemId = R.id.action_favoritos
            setOnItemSelectedListener { item ->
                if (this.selectedItemId == item.itemId) return@setOnItemSelectedListener true
                when (item.itemId) {
                    R.id.action_home -> { startActivity(Intent(this@ActivityFavoritos, ActivityHomeComum::class.java)); true }
                    R.id.action_scan -> { startActivity(Intent(this@ActivityFavoritos, ActivityScanQR::class.java)); true }
                    R.id.action_favoritos -> { true }
                    R.id.action_config -> { startActivity(Intent(this@ActivityFavoritos, ActivityPerfilComum::class.java)); true }
                    else -> false
                }
            }
        }
    }
}

package com.example.indoorar

import android.content.ContentValues
import android.content.Intent
import android.graphics.*
import android.net.Uri
import android.os.Bundle
import android.provider.MediaStore
import android.widget.ImageView
import android.widget.Toast
import androidx.activity.enableEdgeToEdge
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.bumptech.glide.Glide
import com.google.android.material.bottomnavigation.BottomNavigationView
import com.google.android.material.bottomsheet.BottomSheetDialog
import com.google.firebase.firestore.DocumentSnapshot
import com.google.firebase.firestore.FirebaseFirestore
import com.google.firebase.firestore.Query
import com.google.firebase.firestore.ListenerRegistration
import com.google.firebase.storage.FirebaseStorage
import com.google.zxing.BarcodeFormat
import com.google.zxing.EncodeHintType
import com.google.zxing.qrcode.QRCodeWriter
import com.google.zxing.qrcode.decoder.ErrorCorrectionLevel
import java.io.OutputStream
import java.text.SimpleDateFormat
import java.util.*
import android.view.View
import android.widget.Button
import android.widget.TextView
import androidx.core.graphics.createBitmap
import androidx.core.graphics.set
import android.widget.LinearLayout
import androidx.core.graphics.scale

class ActivityHomeComum : BaseActivity() {

    // Substitui Page adapter por adapter de itens individuais
    private val recentAdapter = RecentesAdapter { mapa -> onMapaClicked(mapa) }
    private lateinit var recyclerRecentes: RecyclerView
    private lateinit var progressRecentes: android.widget.ProgressBar
    private lateinit var indicatorsRecentes: LinearLayout
    // Removido snapHelper
    private var recentesListener: ListenerRegistration? = null

    // Auto-scroll
    private val autoScrollHandler = android.os.Handler(android.os.Looper.getMainLooper())
    private var autoScrollRunning = false
    private val autoScrollRunnable = object : Runnable {
        override fun run() {
            if (!autoScrollRunning) return
            recyclerRecentes.scrollBy(2, 0) // velocidade em px
            recycleLoopIfNeeded()
            updateIndicatorFromLayout()
            autoScrollHandler.postDelayed(this, 16) // ~60fps
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        setContentView(R.layout.activity_home_comum)

        // System insets: aplicar somente topo/laterais no root, sem padding inferior
        val mainView = findViewById<View>(R.id.main)
        if (mainView == null) {
            Toast.makeText(this, "Erro: View 'main' não encontrada no layout.", Toast.LENGTH_LONG).show()
            finish()
            return
        }
        androidx.core.view.ViewCompat.setOnApplyWindowInsetsListener(mainView) { v, insets ->
            val systemBars = insets.getInsets(androidx.core.view.WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, 0)
            insets
        }

        // Navbar
        try {
            findViewById<BottomNavigationView>(R.id.bottomNavComum)?.apply {
                // Evita que a própria BottomNavigationView receba padding inferior de insets
                androidx.core.view.ViewCompat.setOnApplyWindowInsetsListener(this) { v, insets ->
                    v.setPadding(v.paddingLeft, v.paddingTop, v.paddingRight, 0)
                    insets
                }

                try { selectedItemId = R.id.action_home } catch (_: Exception) {}

                setOnItemSelectedListener { item ->
                    try {
                        if (this.selectedItemId == item.itemId) return@setOnItemSelectedListener true

                        when (item.itemId) {
                            R.id.action_home -> { startActivity(Intent(this@ActivityHomeComum, ActivityHomeComum::class.java)); true }
                            R.id.action_scan -> { startActivity(Intent(this@ActivityHomeComum, ActivityScanQR::class.java)); true }
                            R.id.action_favoritos -> { startActivity(Intent(this@ActivityHomeComum, ActivityFavoritos::class.java)); true }
                            R.id.action_config -> { startActivity(Intent(this@ActivityHomeComum, ActivityPerfilComum::class.java)); true }
                            else -> false
                        }
                    } catch (e: Exception) {
                        android.util.Log.e("HomeComum", "Erro no bottomNavComum listener", e)
                        false
                    }
                }
            }
        } catch (e: Exception) {
            android.util.Log.e("HomeComum", "Falha ao configurar bottomNavComum", e)
        }


        // Lista de recentes (carrossel horizontal paginado)
        recyclerRecentes = findViewById(R.id.recyclerRecentes)
        progressRecentes = findViewById(R.id.progressRecentes)
        indicatorsRecentes = findViewById(R.id.indicatorsRecentes)

        recyclerRecentes.layoutManager = LinearLayoutManager(this, RecyclerView.HORIZONTAL, false)
        recyclerRecentes.adapter = recentAdapter

        recyclerRecentes.addOnScrollListener(object : RecyclerView.OnScrollListener() {
            override fun onScrolled(recyclerView: RecyclerView, dx: Int, dy: Int) {
                super.onScrolled(recyclerView, dx, dy)
                updateIndicatorFromLayout()
            }
        })

        recyclerRecentes.setOnTouchListener { _, event ->
            when (event.action) {
                android.view.MotionEvent.ACTION_DOWN -> stopAutoScroll()
                android.view.MotionEvent.ACTION_UP, android.view.MotionEvent.ACTION_CANCEL -> autoScrollHandler.postDelayed({ startAutoScroll() }, 2000)
            }
            false
        }

        carregarMapasRecentesEmTempoReal()
    }

    override fun onResume() {
        super.onResume()
        startAutoScroll()
    }

    override fun onPause() {
        stopAutoScroll()
        super.onPause()
    }

    override fun onDestroy() {
        super.onDestroy()
        recentesListener?.remove()
        stopAutoScroll()
    }

    private fun startAutoScroll() {
        if (recentAdapter.itemCount <= 1) return
        if (autoScrollRunning) return
        autoScrollRunning = true
        autoScrollHandler.postDelayed(autoScrollRunnable, 1500) // delay inicial
    }

    private fun stopAutoScroll() {
        autoScrollRunning = false
        autoScrollHandler.removeCallbacks(autoScrollRunnable)
    }

    private fun recycleLoopIfNeeded() {
        val lm = recyclerRecentes.layoutManager as? LinearLayoutManager ?: return
        val last = lm.findLastVisibleItemPosition()
        val total = recentAdapter.itemCount
        if (total > 0 && last >= total - 2) {
            // Reposiciona sem animação para começo para simular loop
            val firstVisible = lm.findFirstVisibleItemPosition()
            val offset = firstVisible % total
            lm.scrollToPosition(offset)
        }
    }

    private fun updateIndicatorFromLayout() {
        val lm = recyclerRecentes.layoutManager as? LinearLayoutManager ?: return
        val first = lm.findFirstVisibleItemPosition()
        val last = lm.findLastVisibleItemPosition()
        if (first == RecyclerView.NO_POSITION || last == RecyclerView.NO_POSITION) return
        val center = (first + last) / 2
        setCurrentIndicator(center % recentAdapter.itemCount)
    }

    private fun buildIndicators(count: Int) {
        indicatorsRecentes.removeAllViews()
        if (count <= 1) { indicatorsRecentes.visibility = View.GONE; return }
        indicatorsRecentes.visibility = View.VISIBLE
        val dm = resources.displayMetrics
        val dotMargin = (4 * dm.density).toInt()
        repeat(count) { idx ->
            val iv = ImageView(this)
            iv.setImageResource(if (idx == 0) R.drawable.dot_selected else R.drawable.dot_unselected)
            val lp = LinearLayout.LayoutParams(LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT)
            lp.setMargins(dotMargin, 0, dotMargin, 0)
            iv.layoutParams = lp
            indicatorsRecentes.addView(iv)
        }
    }

    private fun setCurrentIndicator(index: Int) {
        val n = indicatorsRecentes.childCount
        if (index < 0 || index >= n) return
        for (i in 0 until n) {
            val iv = indicatorsRecentes.getChildAt(i) as? ImageView ?: continue
            iv.setImageResource(if (i == index) R.drawable.dot_selected else R.drawable.dot_unselected)
        }
    }

    private fun imageKeyFor(m: MapaResumo): String {
        val url = m.imagemUrl
        if (!url.isNullOrBlank()) return "url:$url"
        val t = m.imagemBlobThumb?.toBytes()
        if (t != null && t.isNotEmpty()) return "thumb:${t.contentHashCode()}:${t.size}"
        val b = m.imagemBlob?.toBytes()
        if (b != null && b.isNotEmpty()) return "blob:${b.contentHashCode()}:${b.size}"
        return "id:${m.id}"
    }

    private fun carregarMapasRecentesEmTempoReal() {
        progressRecentes.visibility = View.VISIBLE
        recyclerRecentes.visibility = View.GONE
        recentesListener?.remove()
        recentesListener = FirebaseFirestore.getInstance().collection("mapas")
            .orderBy("dataCriacao", Query.Direction.DESCENDING)
            .limit(30)
            .addSnapshotListener { snap, err ->
                if (err != null) {
                    progressRecentes.visibility = View.GONE
                    recyclerRecentes.visibility = View.GONE
                    buildIndicators(0)
                    return@addSnapshotListener
                }
                val lista = snap?.documents?.map { docParaMapaResumoSeguro(it) } ?: emptyList()
                val unicos = lista.distinctBy { imageKeyFor(it) }
                recentAdapter.submit(unicos)
                progressRecentes.visibility = View.GONE
                recyclerRecentes.visibility = if (recentAdapter.itemCount == 0) View.GONE else View.VISIBLE
                buildIndicators(recentAdapter.itemCount)
                updateIndicatorFromLayout()
                startAutoScroll()
            }
    }

    private fun docParaMapaResumoSeguro(doc: DocumentSnapshot): MapaResumo {
        return MapaResumo(
            id = doc.id,
            nome = doc.getString("nome") ?: "Mapa sem nome",
            descricao = doc.getString("descricao") ?: "",
            autorUid = doc.getString("criadorUid") ?: "",
            autorNome = doc.getString("nomeAutor") ?: (doc.getString("criadorUid") ?: ""),
            dataCriacao = doc.getTimestamp("dataCriacao"),
            imagemUrl = doc.getString("imagemUrl"),
            imagemBlob = doc.getBlob("imagemBlob"),
            imagemMime = doc.getString("imagemMime"),
            imagemBlobThumb = doc.getBlob("imagemBlobThumb"),
            imagemMimeThumb = doc.getString("imagemMimeThumb")
        )
    }

    private fun onMapaClicked(m: MapaResumo) {
        val dialog = BottomSheetDialog(this)
        dialog.setContentView(R.layout.bottomsheet_mapa_preview)

        val txtTitulo = dialog.findViewById<TextView>(R.id.txtTituloMapa)
        val txtDesc = dialog.findViewById<TextView>(R.id.txtDescricaoMapa)
        val ivPreview = dialog.findViewById<ImageView>(R.id.ivPreview)
        val btnIniciar = dialog.findViewById<Button>(R.id.btnIniciarNavegacao)
        val btnBaixar = dialog.findViewById<Button>(R.id.btnBaixarQRCode)
        val cardDownload = dialog.findViewById<com.google.android.material.card.MaterialCardView>(R.id.cardDownloadQRCode)
        val btnPDF = dialog.findViewById<Button>(R.id.btnDownloadPDF)
        val btnPNG = dialog.findViewById<Button>(R.id.btnDownloadPNG)

        txtTitulo?.text = m.nome
        txtDesc?.text = m.descricao.ifBlank { "Sem descrição" }

        if (ivPreview != null) {
            val medium = m.imagemBlob?.toBytes()
            val thumb = m.imagemBlobThumb?.toBytes()
            when {
                medium != null && medium.isNotEmpty() -> {
                    Glide.with(ivPreview.context)
                        .load(medium)
                        .centerCrop()
                        .placeholder(R.drawable.ic_minimap_placeholder)
                        .error(R.drawable.ic_minimap_placeholder)
                        .into(ivPreview)
                }
                thumb != null && thumb.isNotEmpty() -> {
                    Glide.with(ivPreview.context)
                        .load(thumb)
                        .centerCrop()
                        .placeholder(R.drawable.ic_minimap_placeholder)
                        .error(R.drawable.ic_minimap_placeholder)
                        .into(ivPreview)
                }
                else -> {
                    val url = m.imagemUrl
                    if (!url.isNullOrBlank()) {
                        if (url.startsWith("gs://")) {
                            val ref = FirebaseStorage.getInstance().getReferenceFromUrl(url)
                            ref.downloadUrl
                                .addOnSuccessListener { httpsUri ->
                                    Glide.with(ivPreview.context)
                                        .load(httpsUri)
                                        .centerCrop()
                                        .placeholder(R.drawable.ic_minimap_placeholder)
                                        .error(R.drawable.ic_minimap_placeholder)
                                        .into(ivPreview)
                                }
                                .addOnFailureListener {
                                    ivPreview.setImageResource(R.drawable.ic_minimap_placeholder)
                                }
                        } else {
                            Glide.with(ivPreview.context)
                                .load(url)
                                .centerCrop()
                                .placeholder(R.drawable.ic_minimap_placeholder)
                                .error(R.drawable.ic_minimap_placeholder)
                                .into(ivPreview)
                        }
                    } else {
                        ivPreview.setImageResource(R.drawable.ic_minimap_placeholder)
                    }
                }
            }
        }

        btnIniciar?.setOnClickListener {
            dialog.dismiss()
            startActivity(Intent(this, ActivityNavHud::class.java).apply {
                putExtra("MAP_ID", m.id)
            })
        }

        btnBaixar?.setOnClickListener {
            // Substituir os botões principais pelos botões de download
            btnIniciar?.visibility = View.GONE
            btnBaixar.visibility = View.GONE
            cardDownload?.visibility = View.VISIBLE
        }

        btnPNG?.setOnClickListener {
            val ok = saveQrAsPng(m.id)
            Toast.makeText(this, if (ok) "QR salvo em Imagens/IndoorAR" else "Falha ao salvar QR", Toast.LENGTH_SHORT).show()
        }
        btnPDF?.setOnClickListener {
            val ok = saveQrAsPdf(m.id)
            Toast.makeText(this, if (ok) "PDF salvo em Downloads" else "Falha ao salvar PDF", Toast.LENGTH_SHORT).show()
        }

        dialog.show()
    }

    private fun generateQrBitmap(content: String, size: Int = 1024): Bitmap? {
        return try {
            val hints = mapOf(
                EncodeHintType.ERROR_CORRECTION to ErrorCorrectionLevel.M,
                EncodeHintType.CHARACTER_SET to "UTF-8",
                EncodeHintType.MARGIN to 1
            )
            val bitMatrix = QRCodeWriter().encode(content, BarcodeFormat.QR_CODE, size, size, hints)
            val width = bitMatrix.width
            val height = bitMatrix.height
            val bmp = createBitmap(width, height)
            for (x in 0 until width) {
                for (y in 0 until height) {
                    bmp[x, y] = if (bitMatrix.get(x, y)) Color.BLACK else Color.WHITE
                }
            }
            bmp
        } catch (_: Exception) { null }
    }

    private fun saveQrAsPng(mapId: String): Boolean {
        val bmp = generateQrBitmap(mapId) ?: return false
        return try {
            val timestamp = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.getDefault()).format(Date())
            val filename = "QR_${mapId}_${timestamp}.png"
            val values = ContentValues().apply {
                put(MediaStore.Images.Media.DISPLAY_NAME, filename)
                put(MediaStore.Images.Media.MIME_TYPE, "image/png")
                put(MediaStore.Images.Media.RELATIVE_PATH, "Pictures/IndoorAR")
                put(MediaStore.Images.Media.IS_PENDING, 1)
            }
            val resolver = contentResolver
            val uri = resolver.insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI, values) ?: return false
            resolver.openOutputStream(uri)?.use { out ->
                bmp.compress(Bitmap.CompressFormat.PNG, 100, out)
            } ?: return false
            values.clear(); values.put(MediaStore.Images.Media.IS_PENDING, 0)
            resolver.update(uri, values, null, null)
            true
        } catch (_: Exception) { false }
    }

    private fun saveQrAsPdf(mapId: String): Boolean {
        return try {
            val bmp = generateQrBitmap(mapId, 1024) ?: return false
            val timestamp = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.getDefault()).format(Date())
            val filename = "QR_${mapId}_${timestamp}.pdf"
            val values = ContentValues().apply {
                put(MediaStore.Downloads.DISPLAY_NAME, filename)
                put(MediaStore.Downloads.MIME_TYPE, "application/pdf")
                put(MediaStore.Downloads.IS_PENDING, 1)
            }
            val resolver = contentResolver
            val collection = MediaStore.Downloads.getContentUri(MediaStore.VOLUME_EXTERNAL_PRIMARY)
            val uri: Uri = resolver.insert(collection, values) ?: return false
            resolver.openOutputStream(uri)?.use { out ->
                writeSimplePdfWithBitmap(bmp, out)
            } ?: return false
            values.clear(); values.put(MediaStore.Downloads.IS_PENDING, 0)
            resolver.update(uri, values, null, null)
            true
        } catch (_: Exception) { false }
    }

    private fun writeSimplePdfWithBitmap(bmp: Bitmap, out: OutputStream) {
        val pageWidth = 595 // A4 width at 72dpi (~8.27in * 72)
        val pageHeight = 842 // A4 height at 72dpi (~11.69in * 72)
        val scale = minOf(pageWidth.toFloat() / bmp.width, pageHeight.toFloat() / bmp.height)
        val pdfBmp = bmp.scale((bmp.width * scale).toInt(), (bmp.height * scale).toInt())
        val document = android.graphics.pdf.PdfDocument()
        val pageInfo = android.graphics.pdf.PdfDocument.PageInfo.Builder(pageWidth, pageHeight, 1).create()
        val page = document.startPage(pageInfo)
        val canvas = page.canvas
        val left = (pageWidth - pdfBmp.width) / 2f
        val top = (pageHeight - pdfBmp.height) / 2f
        canvas.drawColor(Color.WHITE)
        canvas.drawBitmap(pdfBmp, left, top, null)
        document.finishPage(page)
        document.writeTo(out)
        document.close()
        if (!pdfBmp.isRecycled) pdfBmp.recycle()
    }
}

package com.example.indoorar

import android.content.ContentValues
import android.content.Intent
import android.graphics.*
import android.net.Uri
import android.os.Bundle
import android.provider.MediaStore
import android.widget.ImageView
import android.widget.Toast
import androidx.activity.enableEdgeToEdge
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.bumptech.glide.Glide
import com.google.android.material.bottomnavigation.BottomNavigationView
import com.google.android.material.bottomsheet.BottomSheetDialog
import com.google.firebase.firestore.DocumentSnapshot
import com.google.firebase.firestore.FirebaseFirestore
import com.google.firebase.firestore.Query
import com.google.firebase.firestore.ListenerRegistration
import com.google.firebase.storage.FirebaseStorage
import com.google.zxing.BarcodeFormat
import com.google.zxing.EncodeHintType
import com.google.zxing.qrcode.QRCodeWriter
import com.google.zxing.qrcode.decoder.ErrorCorrectionLevel
import java.io.OutputStream
import java.text.SimpleDateFormat
import java.util.*
import android.view.View
import android.widget.Button
import android.widget.TextView
import androidx.core.graphics.createBitmap
import androidx.core.graphics.set
import android.widget.LinearLayout
import androidx.core.graphics.scale

class ActivityHomeComum : BaseActivity() {

    // Substitui Page adapter por adapter de itens individuais
    private val recentAdapter = RecentesAdapter { mapa -> onMapaClicked(mapa) }
    private lateinit var recyclerRecentes: RecyclerView
    private lateinit var progressRecentes: android.widget.ProgressBar
    private lateinit var indicatorsRecentes: LinearLayout
    // Removido snapHelper
    private var recentesListener: ListenerRegistration? = null

    // Auto-scroll config (tuned to be slower & smoother)
    private val SCROLL_STEP_PX = 1            // antes 2
    private val FRAME_DELAY_MS = 30L          // antes 16 (~60fps); agora ~33fps
    private val INITIAL_DELAY_MS = 2500L      // antes 1500ms

    // Auto-scroll
    private val autoScrollHandler = android.os.Handler(android.os.Looper.getMainLooper())
    private var autoScrollRunning = false
    private val autoScrollRunnable = object : Runnable {
        override fun run() {
            if (!autoScrollRunning) return
            recyclerRecentes.scrollBy(SCROLL_STEP_PX, 0)
            recycleLoopIfNeeded()
            updateIndicatorFromLayout()
            autoScrollHandler.postDelayed(this, FRAME_DELAY_MS)
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        setContentView(R.layout.activity_home_comum)

        // System insets: aplicar somente topo/laterais no root, sem padding inferior
        val mainView = findViewById<View>(R.id.main)
        if (mainView == null) {
            Toast.makeText(this, "Erro: View 'main' não encontrada no layout.", Toast.LENGTH_LONG).show()
            finish()
            return
        }
        androidx.core.view.ViewCompat.setOnApplyWindowInsetsListener(mainView) { v, insets ->
            val systemBars = insets.getInsets(androidx.core.view.WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, 0)
            insets
        }

        // Navbar
        try {
            findViewById<BottomNavigationView>(R.id.bottomNavComum)?.apply {
                // Evita que a própria BottomNavigationView receba padding inferior de insets
                androidx.core.view.ViewCompat.setOnApplyWindowInsetsListener(this) { v, insets ->
                    v.setPadding(v.paddingLeft, v.paddingTop, v.paddingRight, 0)
                    insets
                }

                try { selectedItemId = R.id.action_home } catch (_: Exception) {}

                setOnItemSelectedListener { item ->
                    try {
                        if (this.selectedItemId == item.itemId) return@setOnItemSelectedListener true

                        when (item.itemId) {
                            R.id.action_home -> { startActivity(Intent(this@ActivityHomeComum, ActivityHomeComum::class.java)); true }
                            R.id.action_scan -> { startActivity(Intent(this@ActivityHomeComum, ActivityScanQR::class.java)); true }
                            R.id.action_favoritos -> { startActivity(Intent(this@ActivityHomeComum, ActivityFavoritos::class.java)); true }
                            R.id.action_config -> { startActivity(Intent(this@ActivityHomeComum, ActivityPerfilComum::class.java)); true }
                            else -> false
                        }
                    } catch (e: Exception) {
                        android.util.Log.e("HomeComum", "Erro no bottomNavComum listener", e)
                        false
                    }
                }
            }
        } catch (e: Exception) {
            android.util.Log.e("HomeComum", "Falha ao configurar bottomNavComum", e)
        }


        // Lista de recentes (carrossel horizontal paginado)
        recyclerRecentes = findViewById(R.id.recyclerRecentes)
        progressRecentes = findViewById(R.id.progressRecentes)
        indicatorsRecentes = findViewById(R.id.indicatorsRecentes)

        recyclerRecentes.layoutManager = LinearLayoutManager(this, RecyclerView.HORIZONTAL, false)
        recyclerRecentes.adapter = recentAdapter

        recyclerRecentes.addOnScrollListener(object : RecyclerView.OnScrollListener() {
            override fun onScrolled(recyclerView: RecyclerView, dx: Int, dy: Int) {
                super.onScrolled(recyclerView, dx, dy)
                updateIndicatorFromLayout()
            }
        })

        recyclerRecentes.setOnTouchListener { _, event ->
            when (event.action) {
                android.view.MotionEvent.ACTION_DOWN -> stopAutoScroll()
                android.view.MotionEvent.ACTION_UP, android.view.MotionEvent.ACTION_CANCEL -> autoScrollHandler.postDelayed({ startAutoScroll() }, 2000)
            }
            false
        }

        carregarMapasRecentesEmTempoReal()
    }

    override fun onResume() {
        super.onResume()
        startAutoScroll()
    }

    override fun onPause() {
        stopAutoScroll()
        super.onPause()
    }

    override fun onDestroy() {
        super.onDestroy()
        recentesListener?.remove()
        stopAutoScroll()
    }

    private fun startAutoScroll() {
        if (recentAdapter.itemCount <= 1) return
        if (autoScrollRunning) return
        autoScrollRunning = true
        autoScrollHandler.postDelayed(autoScrollRunnable, INITIAL_DELAY_MS)
    }

    private fun stopAutoScroll() {
        autoScrollRunning = false
        autoScrollHandler.removeCallbacks(autoScrollRunnable)
    }

    private fun recycleLoopIfNeeded() {
        val lm = recyclerRecentes.layoutManager as? LinearLayoutManager ?: return
        val last = lm.findLastVisibleItemPosition()
        val total = recentAdapter.itemCount
        if (total > 0 && last >= total - 2) {
            // Reposiciona sem animação para começo para simular loop
            val firstVisible = lm.findFirstVisibleItemPosition()
            val offset = firstVisible % total
            lm.scrollToPosition(offset)
        }
    }

    private fun updateIndicatorFromLayout() {
        val lm = recyclerRecentes.layoutManager as? LinearLayoutManager ?: return
        val first = lm.findFirstVisibleItemPosition()
        val last = lm.findLastVisibleItemPosition()
        if (first == RecyclerView.NO_POSITION || last == RecyclerView.NO_POSITION) return
        val center = (first + last) / 2
        setCurrentIndicator(center % recentAdapter.itemCount)
    }

    private fun buildIndicators(count: Int) {
        indicatorsRecentes.removeAllViews()
        if (count <= 1) { indicatorsRecentes.visibility = View.GONE; return }
        indicatorsRecentes.visibility = View.VISIBLE
        val dm = resources.displayMetrics
        val dotMargin = (4 * dm.density).toInt()
        repeat(count) { idx ->
            val iv = ImageView(this)
            iv.setImageResource(if (idx == 0) R.drawable.dot_selected else R.drawable.dot_unselected)
            val lp = LinearLayout.LayoutParams(LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT)
            lp.setMargins(dotMargin, 0, dotMargin, 0)
            iv.layoutParams = lp
            indicatorsRecentes.addView(iv)
        }
    }

    private fun setCurrentIndicator(index: Int) {
        val n = indicatorsRecentes.childCount
        if (index < 0 || index >= n) return
        for (i in 0 until n) {
            val iv = indicatorsRecentes.getChildAt(i) as? ImageView ?: continue
            iv.setImageResource(if (i == index) R.drawable.dot_selected else R.drawable.dot_unselected)
        }
    }

    private fun imageKeyFor(m: MapaResumo): String {
        val url = m.imagemUrl
        if (!url.isNullOrBlank()) return "url:$url"
        val t = m.imagemBlobThumb?.toBytes()
        if (t != null && t.isNotEmpty()) return "thumb:${t.contentHashCode()}:${t.size}"
        val b = m.imagemBlob?.toBytes()
        if (b != null && b.isNotEmpty()) return "blob:${b.contentHashCode()}:${b.size}"
        return "id:${m.id}"
    }

    private fun carregarMapasRecentesEmTempoReal() {
        progressRecentes.visibility = View.VISIBLE
        recyclerRecentes.visibility = View.GONE
        recentesListener?.remove()
        recentesListener = FirebaseFirestore.getInstance().collection("mapas")
            .orderBy("dataCriacao", Query.Direction.DESCENDING)
            .limit(30)
            .addSnapshotListener { snap, err ->
                if (err != null) {
                    progressRecentes.visibility = View.GONE
                    recyclerRecentes.visibility = View.GONE
                    buildIndicators(0)
                    return@addSnapshotListener
                }
                val lista = snap?.documents?.map { docParaMapaResumoSeguro(it) } ?: emptyList()
                val unicos = lista.distinctBy { imageKeyFor(it) }
                val limited = unicos.take(5)
                recentAdapter.submit(limited)
                progressRecentes.visibility = View.GONE
                recyclerRecentes.visibility = if (recentAdapter.itemCount == 0) View.GONE else View.VISIBLE
                buildIndicators(recentAdapter.itemCount)
                updateIndicatorFromLayout()
                startAutoScroll()
            }
    }

    private fun docParaMapaResumoSeguro(doc: DocumentSnapshot): MapaResumo {
        return MapaResumo(
            id = doc.id,
            nome = doc.getString("nome") ?: "Mapa sem nome",
            descricao = doc.getString("descricao") ?: "",
            autorUid = doc.getString("criadorUid") ?: "",
            autorNome = doc.getString("nomeAutor") ?: (doc.getString("criadorUid") ?: ""),
            dataCriacao = doc.getTimestamp("dataCriacao"),
            imagemUrl = doc.getString("imagemUrl"),
            imagemBlob = doc.getBlob("imagemBlob"),
            imagemMime = doc.getString("imagemMime"),
            imagemBlobThumb = doc.getBlob("imagemBlobThumb"),
            imagemMimeThumb = doc.getString("imagemMimeThumb")
        )
    }

    private fun onMapaClicked(m: MapaResumo) {
        val dialog = BottomSheetDialog(this)
        dialog.setContentView(R.layout.bottomsheet_mapa_preview)

        val txtTitulo = dialog.findViewById<TextView>(R.id.txtTituloMapa)
        val txtDesc = dialog.findViewById<TextView>(R.id.txtDescricaoMapa)
        val ivPreview = dialog.findViewById<ImageView>(R.id.ivPreview)
        val btnIniciar = dialog.findViewById<Button>(R.id.btnIniciarNavegacao)
        val btnBaixar = dialog.findViewById<Button>(R.id.btnBaixarQRCode)
        val cardDownload = dialog.findViewById<com.google.android.material.card.MaterialCardView>(R.id.cardDownloadQRCode)
        val btnPDF = dialog.findViewById<Button>(R.id.btnDownloadPDF)
        val btnPNG = dialog.findViewById<Button>(R.id.btnDownloadPNG)

        txtTitulo?.text = m.nome
        txtDesc?.text = m.descricao.ifBlank { "Sem descrição" }

        if (ivPreview != null) {
            val medium = m.imagemBlob?.toBytes()
            val thumb = m.imagemBlobThumb?.toBytes()
            when {
                medium != null && medium.isNotEmpty() -> {
                    Glide.with(ivPreview.context)
                        .load(medium)
                        .centerCrop()
                        .placeholder(R.drawable.ic_minimap_placeholder)
                        .error(R.drawable.ic_minimap_placeholder)
                        .into(ivPreview)
                }
                thumb != null && thumb.isNotEmpty() -> {
                    Glide.with(ivPreview.context)
                        .load(thumb)
                        .centerCrop()
                        .placeholder(R.drawable.ic_minimap_placeholder)
                        .error(R.drawable.ic_minimap_placeholder)
                        .into(ivPreview)
                }
                else -> {
                    val url = m.imagemUrl
                    if (!url.isNullOrBlank()) {
                        if (url.startsWith("gs://")) {
                            val ref = FirebaseStorage.getInstance().getReferenceFromUrl(url)
                            ref.downloadUrl
                                .addOnSuccessListener { httpsUri ->
                                    Glide.with(ivPreview.context)
                                        .load(httpsUri)
                                        .centerCrop()
                                        .placeholder(R.drawable.ic_minimap_placeholder)
                                        .error(R.drawable.ic_minimap_placeholder)
                                        .into(ivPreview)
                                }
                                .addOnFailureListener {
                                    ivPreview.setImageResource(R.drawable.ic_minimap_placeholder)
                                }
                        } else {
                            Glide.with(ivPreview.context)
                                .load(url)
                                .centerCrop()
                                .placeholder(R.drawable.ic_minimap_placeholder)
                                .error(R.drawable.ic_minimap_placeholder)
                                .into(ivPreview)
                        }
                    } else {
                        ivPreview.setImageResource(R.drawable.ic_minimap_placeholder)
                    }
                }
            }
        }

        btnIniciar?.setOnClickListener {
            dialog.dismiss()
            startActivity(Intent(this, ActivityNavHud::class.java).apply {
                putExtra("MAP_ID", m.id)
            })
        }

        btnBaixar?.setOnClickListener {
            // Substituir os botões principais pelos botões de download
            btnIniciar?.visibility = View.GONE
            btnBaixar.visibility = View.GONE
            cardDownload?.visibility = View.VISIBLE
        }

        btnPNG?.setOnClickListener {
            val ok = saveQrAsPng(m.id)
            Toast.makeText(this, if (ok) "QR salvo em Imagens/IndoorAR" else "Falha ao salvar QR", Toast.LENGTH_SHORT).show()
        }
        btnPDF?.setOnClickListener {
            val ok = saveQrAsPdf(m.id)
            Toast.makeText(this, if (ok) "PDF salvo em Downloads" else "Falha ao salvar PDF", Toast.LENGTH_SHORT).show()
        }

        dialog.show()
    }

    private fun generateQrBitmap(content: String, size: Int = 1024): Bitmap? {
        return try {
            val hints = mapOf(
                EncodeHintType.ERROR_CORRECTION to ErrorCorrectionLevel.M,
                EncodeHintType.CHARACTER_SET to "UTF-8",
                EncodeHintType.MARGIN to 1
            )
            val bitMatrix = QRCodeWriter().encode(content, BarcodeFormat.QR_CODE, size, size, hints)
            val width = bitMatrix.width
            val height = bitMatrix.height
            val bmp = createBitmap(width, height)
            for (x in 0 until width) {
                for (y in 0 until height) {
                    bmp[x, y] = if (bitMatrix.get(x, y)) Color.BLACK else Color.WHITE
                }
            }
            bmp
        } catch (_: Exception) { null }
    }

    private fun saveQrAsPng(mapId: String): Boolean {
        val bmp = generateQrBitmap(mapId) ?: return false
        return try {
            val timestamp = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.getDefault()).format(Date())
            val filename = "QR_${mapId}_${timestamp}.png"
            val values = ContentValues().apply {
                put(MediaStore.Images.Media.DISPLAY_NAME, filename)
                put(MediaStore.Images.Media.MIME_TYPE, "image/png")
                put(MediaStore.Images.Media.RELATIVE_PATH, "Pictures/IndoorAR")
                put(MediaStore.Images.Media.IS_PENDING, 1)
            }
            val resolver = contentResolver
            val uri = resolver.insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI, values) ?: return false
            resolver.openOutputStream(uri)?.use { out ->
                bmp.compress(Bitmap.CompressFormat.PNG, 100, out)
            } ?: return false
            values.clear(); values.put(MediaStore.Images.Media.IS_PENDING, 0)
            resolver.update(uri, values, null, null)
            true
        } catch (_: Exception) { false }
    }

    private fun saveQrAsPdf(mapId: String): Boolean {
        return try {
            val bmp = generateQrBitmap(mapId, 1024) ?: return false
            val timestamp = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.getDefault()).format(Date())
            val filename = "QR_${mapId}_${timestamp}.pdf"
            val values = ContentValues().apply {
                put(MediaStore.Downloads.DISPLAY_NAME, filename)
                put(MediaStore.Downloads.MIME_TYPE, "application/pdf")
                put(MediaStore.Downloads.IS_PENDING, 1)
            }
            val resolver = contentResolver
            val collection = MediaStore.Downloads.getContentUri(MediaStore.VOLUME_EXTERNAL_PRIMARY)
            val uri: Uri = resolver.insert(collection, values) ?: return false
            resolver.openOutputStream(uri)?.use { out ->
                writeSimplePdfWithBitmap(bmp, out)
            } ?: return false
            values.clear(); values.put(MediaStore.Downloads.IS_PENDING, 0)
            resolver.update(uri, values, null, null)
            true
        } catch (_: Exception) { false }
    }

    private fun writeSimplePdfWithBitmap(bmp: Bitmap, out: OutputStream) {
        val pageWidth = 595 // A4 width at 72dpi (~8.27in * 72)
        val pageHeight = 842 // A4 height at 72dpi (~11.69in * 72)
        val scale = minOf(pageWidth.toFloat() / bmp.width, pageHeight.toFloat() / bmp.height)
        val pdfBmp = bmp.scale((bmp.width * scale).toInt(), (bmp.height * scale).toInt())
        val document = android.graphics.pdf.PdfDocument()
        val pageInfo = android.graphics.pdf.PdfDocument.PageInfo.Builder(pageWidth, pageHeight, 1).create()
        val page = document.startPage(pageInfo)
        val canvas = page.canvas
        val left = (pageWidth - pdfBmp.width) / 2f
        val top = (pageHeight - pdfBmp.height) / 2f
        canvas.drawColor(Color.WHITE)
        canvas.drawBitmap(pdfBmp, left, top, null)
        document.finishPage(page)
        document.writeTo(out)
        document.close()
        if (!pdfBmp.isRecycled) pdfBmp.recycle()
    }
}

package com.example.indoorar

import android.content.Intent
import android.os.Bundle
import android.util.Log
import android.view.View
import android.widget.ImageView
import android.widget.ProgressBar
import android.widget.TextView
import androidx.activity.enableEdgeToEdge
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.firestore.DocumentSnapshot
import com.google.firebase.firestore.FirebaseFirestore
import com.google.firebase.firestore.ListenerRegistration
import android.widget.LinearLayout
import androidx.core.graphics.set
import androidx.core.graphics.scale
import androidx.core.graphics.createBitmap
import com.google.android.material.bottomnavigation.BottomNavigationView

class ActivityHomeMaker : BaseActivity() {

    private lateinit var recyclerRecentes: RecyclerView
    private lateinit var progressRecentes: ProgressBar
    private lateinit var indicatorsRecentes: LinearLayout
    private var recentesListener: ListenerRegistration? = null

    // Substitui pages por itens individuais
    private val recentAdapter = RecentesAdapter { mapa -> onMapaClicked(mapa) }

    // Auto-scroll contínuo
    private val autoScrollHandler = android.os.Handler(android.os.Looper.getMainLooper())
    private var autoScrollRunning = false
    private val autoScrollRunnable = object : Runnable {
        override fun run() {
            if (!autoScrollRunning) return
            recyclerRecentes.scrollBy(2, 0)
            recycleLoopIfNeeded()
            updateIndicatorFromLayout()
            autoScrollHandler.postDelayed(this, 16)
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        setContentView(R.layout.activity_home_maker)

        // Aplicar insets apenas no topo e laterais do root
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, 0)
            insets
        }

        // Texto de boas-vindas
        findViewById<TextView>(R.id.txtBemVindo).text = getString(R.string.bem_vindo)


        // Navbar
        try {
            findViewById<BottomNavigationView>(R.id.bottomNavMaker)?.apply {
                // Evitar aplicar padding inferior de insets na navbar
                ViewCompat.setOnApplyWindowInsetsListener(this) { v, insets ->
                    v.setPadding(v.paddingLeft, v.paddingTop, v.paddingRight, 0)
                    insets
                }

                try {
                    selectedItemId = R.id.action_home
                } catch (_: Exception) {}

                setOnItemSelectedListener { item ->
                    try {
                        if (this.selectedItemId == item.itemId) return@setOnItemSelectedListener true

                        when (item.itemId) {
                            R.id.action_home -> { startActivity(Intent(this@ActivityHomeMaker, ActivityHomeMaker::class.java)); true }
                            R.id.action_criar -> { startActivity(Intent(this@ActivityHomeMaker, com.example.indoorar.ui.ActivityEditor::class.java)); true }
                            R.id.action_estatisticas -> { startActivity(Intent(this@ActivityHomeMaker, ActivityEstatisticas::class.java)); true }
                            R.id.action_config -> { startActivity(Intent(this@ActivityHomeMaker, ActivityPerfilMaker::class.java)); true }
                            else -> false
                        }
                    } catch (e: Exception) {
                        Log.e("HomeMaker", "Erro no bottomNavMaker listener", e)
                        false
                    }
                }
            }
        } catch (e: Exception) {
            Log.e("HomeMaker", "Falha ao configurar bottomNavMaker", e)
        }

        // Views de recentes (carrossel horizontal paginado)
        recyclerRecentes = findViewById(R.id.recyclerRecentes)
        progressRecentes = findViewById(R.id.progressRecentes)
        indicatorsRecentes = findViewById(R.id.indicatorsRecentes)

        recyclerRecentes.layoutManager = LinearLayoutManager(this, RecyclerView.HORIZONTAL, false)
        recyclerRecentes.adapter = recentAdapter

        recyclerRecentes.addOnScrollListener(object : RecyclerView.OnScrollListener() {
            override fun onScrolled(recyclerView: RecyclerView, dx: Int, dy: Int) {
                super.onScrolled(recyclerView, dx, dy)
                updateIndicatorFromLayout()
            }
        })
        recyclerRecentes.setOnTouchListener { _, event ->
            when (event.action) {
                android.view.MotionEvent.ACTION_DOWN -> stopAutoScroll()
                android.view.MotionEvent.ACTION_UP, android.view.MotionEvent.ACTION_CANCEL -> autoScrollHandler.postDelayed({ startAutoScroll() }, 2000)
            }
            false
        }

        carregarMapasRecentesEmTempoReal()
    }

    override fun onResume() { super.onResume(); startAutoScroll() }
    override fun onPause() { stopAutoScroll(); super.onPause() }
    override fun onDestroy() { super.onDestroy(); recentesListener?.remove(); stopAutoScroll() }

    private fun startAutoScroll() {
        if (recentAdapter.itemCount <= 1) return
        if (autoScrollRunning) return
        autoScrollRunning = true
        autoScrollHandler.postDelayed(autoScrollRunnable, 1500)
    }
    private fun stopAutoScroll() { autoScrollRunning = false; autoScrollHandler.removeCallbacks(autoScrollRunnable) }

    private fun recycleLoopIfNeeded() {
        val lm = recyclerRecentes.layoutManager as? LinearLayoutManager ?: return
        val last = lm.findLastVisibleItemPosition()
        val total = recentAdapter.itemCount
        if (total > 0 && last >= total - 2) {
            val firstVisible = lm.findFirstVisibleItemPosition()
            val offset = firstVisible % total
            lm.scrollToPosition(offset)
        }
    }

    private fun updateIndicatorFromLayout() {
        val lm = recyclerRecentes.layoutManager as? LinearLayoutManager ?: return
        val first = lm.findFirstVisibleItemPosition()
        val last = lm.findLastVisibleItemPosition()
        if (first == RecyclerView.NO_POSITION || last == RecyclerView.NO_POSITION) return
        val center = (first + last) / 2
        setCurrentIndicator(center % recentAdapter.itemCount)
    }

    private fun imageKeyFor(m: MapaResumo): String {
        val url = m.imagemUrl
        if (!url.isNullOrBlank()) return "url:$url"
        val t = m.imagemBlobThumb?.toBytes(); if (t != null && t.isNotEmpty()) return "thumb:${t.contentHashCode()}:${t.size}"
        val b = m.imagemBlob?.toBytes(); if (b != null && b.isNotEmpty()) return "blob:${b.contentHashCode()}:${b.size}"
        return "id:${m.id}"
    }

    private fun carregarMapasRecentesEmTempoReal() {
        val uid = FirebaseAuth.getInstance().currentUser?.uid
        if (uid == null) {
            // vazio/sem usuário: esconder lista e indicadores
            progressRecentes.visibility = View.GONE
            recyclerRecentes.visibility = View.GONE
            buildIndicators(0)
            return
        }
        progressRecentes.visibility = View.VISIBLE
        recyclerRecentes.visibility = View.GONE

        recentesListener?.remove()
        recentesListener = FirebaseFirestore.getInstance().collection("mapas")
            .whereEqualTo("criadorUid", uid)
            .limit(200)
            .addSnapshotListener { snap, err ->
                if (err != null) {
                    progressRecentes.visibility = View.GONE
                    recyclerRecentes.visibility = View.GONE
                    buildIndicators(0)
                    return@addSnapshotListener
                }
                val lista = snap?.documents?.map { docParaMapaResumoMaker(it, uid) } ?: emptyList()
                val ordenada = lista.sortedByDescending { it.dataCriacao?.seconds ?: 0 }
                val unicos = ordenada.distinctBy { imageKeyFor(it) }
                recentAdapter.submit(unicos)
                progressRecentes.visibility = View.GONE
                recyclerRecentes.visibility = if (recentAdapter.itemCount == 0) View.GONE else View.VISIBLE
                buildIndicators(recentAdapter.itemCount)
                updateIndicatorFromLayout()
                startAutoScroll()
            }
    }

    private fun docParaMapaResumoMaker(doc: DocumentSnapshot, uid: String): MapaResumo {
        return MapaResumo(
            id = doc.id,
            nome = doc.getString("nome") ?: "Mapa sem nome",
            descricao = doc.getString("descricao") ?: "",
            autorUid = uid,
            autorNome = doc.getString("nomeAutor") ?: uid,
            dataCriacao = doc.getTimestamp("dataCriacao"),
            imagemUrl = doc.getString("imagemUrl"),
            imagemBlob = doc.getBlob("imagemBlob"),
            imagemMime = doc.getString("imagemMime"),
            imagemBlobThumb = doc.getBlob("imagemBlobThumb"),
            imagemMimeThumb = doc.getString("imagemMimeThumb")
        )
    }

    private fun buildIndicators(count: Int) {
        indicatorsRecentes.removeAllViews()
        if (count <= 1) {
            indicatorsRecentes.visibility = View.GONE
            return
        }
        indicatorsRecentes.visibility = View.VISIBLE
        val dm = resources.displayMetrics
        val dotMargin = (4 * dm.density).toInt()
        repeat(count) { idx ->
            val iv = ImageView(this)
            iv.setImageResource(if (idx == 0) R.drawable.dot_selected else R.drawable.dot_unselected)
            val lp = LinearLayout.LayoutParams(LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT)
            lp.setMargins(dotMargin, 0, dotMargin, 0)
            iv.layoutParams = lp
            indicatorsRecentes.addView(iv)
        }
    }

    private fun setCurrentIndicator(index: Int) {
        val n = indicatorsRecentes.childCount
        if (index < 0 || index >= n) return
        for (i in 0 until n) {
            val iv = indicatorsRecentes.getChildAt(i) as? ImageView ?: continue
            iv.setImageResource(if (i == index) R.drawable.dot_selected else R.drawable.dot_unselected)
        }
    }

    private fun onMapaClicked(m: MapaResumo) {
        val dialog = com.google.android.material.bottomsheet.BottomSheetDialog(this)
        dialog.setContentView(R.layout.bottomsheet_mapa_preview)

        val txtTitulo = dialog.findViewById<TextView>(R.id.txtTituloMapa)
        val txtDesc = dialog.findViewById<TextView>(R.id.txtDescricaoMapa)
        val ivPreview = dialog.findViewById<ImageView>(R.id.ivPreview)
        val btnIniciar = dialog.findViewById<android.widget.Button>(R.id.btnIniciarNavegacao)
        val btnBaixar = dialog.findViewById<android.widget.Button>(R.id.btnBaixarQRCode)
        val cardDownload = dialog.findViewById<com.google.android.material.card.MaterialCardView>(R.id.cardDownloadQRCode)
        val btnPDF = dialog.findViewById<android.widget.Button>(R.id.btnDownloadPDF)
        val btnPNG = dialog.findViewById<android.widget.Button>(R.id.btnDownloadPNG)

        txtTitulo?.text = m.nome
        txtDesc?.text = m.descricao.ifBlank { "Sem descrição" }

        // Carrega preview (thumb/medium/url)
        if (ivPreview != null) {
            val medium = m.imagemBlob?.toBytes()
            val thumb = m.imagemBlobThumb?.toBytes()
            when {
                medium != null && medium.isNotEmpty() -> {
                    com.bumptech.glide.Glide.with(ivPreview.context)
                        .load(medium)
                        .centerCrop()
                        .placeholder(R.drawable.ic_minimap_placeholder)
                        .error(R.drawable.ic_minimap_placeholder)
                        .into(ivPreview)
                }
                thumb != null && thumb.isNotEmpty() -> {
                    com.bumptech.glide.Glide.with(ivPreview.context)
                        .load(thumb)
                        .centerCrop()
                        .placeholder(R.drawable.ic_minimap_placeholder)
                        .error(R.drawable.ic_minimap_placeholder)
                        .into(ivPreview)
                }
                else -> {
                    val url = m.imagemUrl
                    if (!url.isNullOrBlank()) {
                        if (url.startsWith("gs://")) {
                            val ref = com.google.firebase.storage.FirebaseStorage.getInstance().getReferenceFromUrl(url)
                            ref.downloadUrl
                                .addOnSuccessListener { httpsUri ->
                                    com.bumptech.glide.Glide.with(ivPreview.context)
                                        .load(httpsUri)
                                        .centerCrop()
                                        .placeholder(R.drawable.ic_minimap_placeholder)
                                        .error(R.drawable.ic_minimap_placeholder)
                                        .into(ivPreview)
                                }
                                .addOnFailureListener {
                                    ivPreview.setImageResource(R.drawable.ic_minimap_placeholder)
                                }
                        } else {
                            com.bumptech.glide.Glide.with(ivPreview.context)
                                .load(url)
                                .centerCrop()
                                .placeholder(R.drawable.ic_minimap_placeholder)
                                .error(R.drawable.ic_minimap_placeholder)
                                .into(ivPreview)
                        }
                    } else {
                        ivPreview.setImageResource(R.drawable.ic_minimap_placeholder)
                    }
                }
            }
        }

        btnIniciar?.setOnClickListener {
            dialog.dismiss()
            startActivity(Intent(this, ActivityNavHud::class.java).apply {
                putExtra("MAP_ID", m.id)
            })
        }

        btnBaixar?.setOnClickListener {
            // Substituir os botões principais pelos botões de download
            btnIniciar?.visibility = View.GONE
            btnBaixar.visibility = View.GONE
            cardDownload?.visibility = View.VISIBLE
        }

        btnPNG?.setOnClickListener {
            val ok = saveQrAsPng(m.id)
            android.widget.Toast.makeText(this, if (ok) "QR salvo em Imagens/IndoorAR" else "Falha ao salvar QR", android.widget.Toast.LENGTH_SHORT).show()
        }
        btnPDF?.setOnClickListener {
            val ok = saveQrAsPdf(m.id)
            android.widget.Toast.makeText(this, if (ok) "PDF salvo em Downloads" else "Falha ao salvar PDF", android.widget.Toast.LENGTH_SHORT).show()
        }

        dialog.show()
    }

    private fun generateQrBitmap(content: String, size: Int = 1024): android.graphics.Bitmap? {
        return try {
            val hints = mapOf(
                com.google.zxing.EncodeHintType.ERROR_CORRECTION to com.google.zxing.qrcode.decoder.ErrorCorrectionLevel.M,
                com.google.zxing.EncodeHintType.CHARACTER_SET to "UTF-8",
                com.google.zxing.EncodeHintType.MARGIN to 1
            )
            val bitMatrix = com.google.zxing.qrcode.QRCodeWriter().encode(content, com.google.zxing.BarcodeFormat.QR_CODE, size, size, hints)
            val width = bitMatrix.width
            val height = bitMatrix.height
            val bmp = createBitmap(width, height)
            for (x in 0 until width) {
                for (y in 0 until height) {
                    bmp[x, y] = if (bitMatrix.get(x, y)) android.graphics.Color.BLACK else android.graphics.Color.WHITE
                }
            }
            bmp
        } catch (_: Exception) { null }
    }

    private fun saveQrAsPng(mapId: String): Boolean {
        val bmp = generateQrBitmap(mapId) ?: return false
        return try {
            val filename = "QR_${mapId}_${java.text.SimpleDateFormat("yyyyMMdd_HHmmss", java.util.Locale.getDefault()).format(java.util.Date())}.png"
            val values = android.content.ContentValues().apply {
                put(android.provider.MediaStore.Images.Media.DISPLAY_NAME, filename)
                put(android.provider.MediaStore.Images.Media.MIME_TYPE, "image/png")
                put(android.provider.MediaStore.Images.Media.RELATIVE_PATH, "Pictures/IndoorAR")
                put(android.provider.MediaStore.Images.Media.IS_PENDING, 1)
            }
            val resolver = contentResolver
            val uri = resolver.insert(android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI, values) ?: return false
            resolver.openOutputStream(uri)?.use { out ->
                bmp.compress(android.graphics.Bitmap.CompressFormat.PNG, 100, out)
            } ?: return false
            values.clear(); values.put(android.provider.MediaStore.Images.Media.IS_PENDING, 0)
            resolver.update(uri, values, null, null)
            true
        } catch (_: Exception) { false }
    }

    private fun saveQrAsPdf(mapId: String): Boolean {
        return try {
            val bmp = generateQrBitmap(mapId, 1024) ?: return false
            val filename = "QR_${mapId}_${java.text.SimpleDateFormat("yyyyMMdd_HHmmss", java.util.Locale.getDefault()).format(java.util.Date())}.pdf"
            val values = android.content.ContentValues().apply {
                put(android.provider.MediaStore.Downloads.DISPLAY_NAME, filename)
                put(android.provider.MediaStore.Downloads.MIME_TYPE, "application/pdf")
                put(android.provider.MediaStore.Downloads.IS_PENDING, 1)
            }
            val resolver = contentResolver
            val collection = android.provider.MediaStore.Downloads.getContentUri(android.provider.MediaStore.VOLUME_EXTERNAL_PRIMARY)
            val uri: android.net.Uri = resolver.insert(collection, values) ?: return false
            resolver.openOutputStream(uri)?.use { out ->
                writeSimplePdfWithBitmap(bmp, out)
            } ?: return false
            values.clear(); values.put(android.provider.MediaStore.Downloads.IS_PENDING, 0)
            resolver.update(uri, values, null, null)
            true
        } catch (_: Exception) { false }
    }

    private fun writeSimplePdfWithBitmap(bmp: android.graphics.Bitmap, out: java.io.OutputStream) {
        val pageWidth = 595 // A4 width at 72dpi (~8.27in * 72)
        val pageHeight = 842 // A4 height at 72dpi (~11.69in * 72)
        val scale =
            kotlin.math.min(pageWidth.toFloat() / bmp.width, pageHeight.toFloat() / bmp.height)
        val scaled = bmp.scale((bmp.width * scale).toInt(), (bmp.height * scale).toInt())
        val document = android.graphics.pdf.PdfDocument()
        val pageInfo = android.graphics.pdf.PdfDocument.PageInfo.Builder(pageWidth, pageHeight, 1).create()
        val page = document.startPage(pageInfo)
        val canvas = page.canvas
        val left = (pageWidth - scaled.width) / 2f
        val top = (pageHeight - scaled.height) / 2f
        canvas.drawColor(android.graphics.Color.WHITE)
        canvas.drawBitmap(scaled, left, top, null)
        document.finishPage(page)
        document.writeTo(out)
        document.close()
        if (!scaled.isRecycled) scaled.recycle()
    }
}

package com.example.indoorar

import android.content.Intent
import android.os.Bundle
import android.util.Log
import android.view.View
import android.widget.ImageView
import android.widget.ProgressBar
import android.widget.TextView
import androidx.activity.enableEdgeToEdge
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.google.firebase.auth.FirebaseAuth
import com.google.firebase.firestore.DocumentSnapshot
import com.google.firebase.firestore.FirebaseFirestore
import com.google.firebase.firestore.ListenerRegistration
import android.widget.LinearLayout
import androidx.core.graphics.set
import androidx.core.graphics.scale
import androidx.core.graphics.createBitmap
import com.google.android.material.bottomnavigation.BottomNavigationView

class ActivityHomeMaker : BaseActivity() {

    private lateinit var recyclerRecentes: RecyclerView
    private lateinit var progressRecentes: ProgressBar
    private lateinit var indicatorsRecentes: LinearLayout
    private var recentesListener: ListenerRegistration? = null

    // Substitui pages por itens individuais
    private val recentAdapter = RecentesAdapter { mapa -> onMapaClicked(mapa) }

    // Auto-scroll config (slower like Home Comum)
    private val SCROLL_STEP_PX = 1
    private val FRAME_DELAY_MS = 30L
    private val INITIAL_DELAY_MS = 2500L

    private val autoScrollHandler = android.os.Handler(android.os.Looper.getMainLooper())
    private var autoScrollRunning = false
    private val autoScrollRunnable = object : Runnable {
        override fun run() {
            if (!autoScrollRunning) return
            recyclerRecentes.scrollBy(SCROLL_STEP_PX, 0)
            recycleLoopIfNeeded()
            updateIndicatorFromLayout()
            autoScrollHandler.postDelayed(this, FRAME_DELAY_MS)
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        setContentView(R.layout.activity_home_maker)

        // Aplicar insets apenas no topo e laterais do root
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, 0)
            insets
        }

        // Texto de boas-vindas
        findViewById<TextView>(R.id.txtBemVindo).text = getString(R.string.bem_vindo)


        // Navbar
        try {
            findViewById<BottomNavigationView>(R.id.bottomNavMaker)?.apply {
                // Evitar aplicar padding inferior de insets na navbar
                ViewCompat.setOnApplyWindowInsetsListener(this) { v, insets ->
                    v.setPadding(v.paddingLeft, v.paddingTop, v.paddingRight, 0)
                    insets
                }

                try {
                    selectedItemId = R.id.action_home
                } catch (_: Exception) {}

                setOnItemSelectedListener { item ->
                    try {
                        if (this.selectedItemId == item.itemId) return@setOnItemSelectedListener true

                        when (item.itemId) {
                            R.id.action_home -> { startActivity(Intent(this@ActivityHomeMaker, ActivityHomeMaker::class.java)); true }
                            R.id.action_criar -> { startActivity(Intent(this@ActivityHomeMaker, com.example.indoorar.ui.ActivityEditor::class.java)); true }
                            R.id.action_estatisticas -> { startActivity(Intent(this@ActivityHomeMaker, ActivityEstatisticas::class.java)); true }
                            R.id.action_config -> { startActivity(Intent(this@ActivityHomeMaker, ActivityPerfilMaker::class.java)); true }
                            else -> false
                        }
                    } catch (e: Exception) {
                        Log.e("HomeMaker", "Erro no bottomNavMaker listener", e)
                        false
                    }
                }
            }
        } catch (e: Exception) {
            Log.e("HomeMaker", "Falha ao configurar bottomNavMaker", e)
        }

        // Views de recentes (carrossel horizontal paginado)
        recyclerRecentes = findViewById(R.id.recyclerRecentes)
        progressRecentes = findViewById(R.id.progressRecentes)
        indicatorsRecentes = findViewById(R.id.indicatorsRecentes)

        recyclerRecentes.layoutManager = LinearLayoutManager(this, RecyclerView.HORIZONTAL, false)
        recyclerRecentes.adapter = recentAdapter

        recyclerRecentes.addOnScrollListener(object : RecyclerView.OnScrollListener() {
            override fun onScrolled(recyclerView: RecyclerView, dx: Int, dy: Int) {
                super.onScrolled(recyclerView, dx, dy)
                updateIndicatorFromLayout()
            }
        })
        recyclerRecentes.setOnTouchListener { _, event ->
            when (event.action) {
                android.view.MotionEvent.ACTION_DOWN -> stopAutoScroll()
                android.view.MotionEvent.ACTION_UP, android.view.MotionEvent.ACTION_CANCEL -> autoScrollHandler.postDelayed({ startAutoScroll() }, 2000)
            }
            false
        }

        carregarMapasRecentesEmTempoReal()
    }

    override fun onResume() { super.onResume(); startAutoScroll() }
    override fun onPause() { stopAutoScroll(); super.onPause() }
    override fun onDestroy() { super.onDestroy(); recentesListener?.remove(); stopAutoScroll() }

    private fun startAutoScroll() {
        if (recentAdapter.itemCount <= 1) return
        if (autoScrollRunning) return
        autoScrollRunning = true
        autoScrollHandler.postDelayed(autoScrollRunnable, INITIAL_DELAY_MS)
    }
    private fun stopAutoScroll() { autoScrollRunning = false; autoScrollHandler.removeCallbacks(autoScrollRunnable) }

    private fun recycleLoopIfNeeded() {
        val lm = recyclerRecentes.layoutManager as? LinearLayoutManager ?: return
        val last = lm.findLastVisibleItemPosition()
        val total = recentAdapter.itemCount
        if (total > 0 && last >= total - 2) {
            val firstVisible = lm.findFirstVisibleItemPosition()
            val offset = firstVisible % total
            lm.scrollToPosition(offset)
        }
    }

    private fun updateIndicatorFromLayout() {
        val lm = recyclerRecentes.layoutManager as? LinearLayoutManager ?: return
        val first = lm.findFirstVisibleItemPosition()
        val last = lm.findLastVisibleItemPosition()
        if (first == RecyclerView.NO_POSITION || last == RecyclerView.NO_POSITION) return
        val center = (first + last) / 2
        setCurrentIndicator(center % recentAdapter.itemCount)
    }

    private fun imageKeyFor(m: MapaResumo): String {
        val url = m.imagemUrl
        if (!url.isNullOrBlank()) return "url:$url"
        val t = m.imagemBlobThumb?.toBytes(); if (t != null && t.isNotEmpty()) return "thumb:${t.contentHashCode()}:${t.size}"
        val b = m.imagemBlob?.toBytes(); if (b != null && b.isNotEmpty()) return "blob:${b.contentHashCode()}:${b.size}"
        return "id:${m.id}"
    }

    private fun carregarMapasRecentesEmTempoReal() {
        val uid = FirebaseAuth.getInstance().currentUser?.uid
        if (uid == null) {
            // vazio/sem usuário: esconder lista e indicadores
            progressRecentes.visibility = View.GONE
            recyclerRecentes.visibility = View.GONE
            buildIndicators(0)
            return
        }
        progressRecentes.visibility = View.VISIBLE
        recyclerRecentes.visibility = View.GONE

        recentesListener?.remove()
        recentesListener = FirebaseFirestore.getInstance().collection("mapas")
            .whereEqualTo("criadorUid", uid)
            .limit(200)
            .addSnapshotListener { snap, err ->
                if (err != null) {
                    progressRecentes.visibility = View.GONE
                    recyclerRecentes.visibility = View.GONE
                    buildIndicators(0)
                    return@addSnapshotListener
                }
                val lista = snap?.documents?.map { docParaMapaResumoMaker(it, uid) } ?: emptyList()
                val ordenada = lista.sortedByDescending { it.dataCriacao?.seconds ?: 0 }
                val unicos = ordenada.distinctBy { imageKeyFor(it) }
                val limited = unicos.take(5)
                recentAdapter.submit(limited)
                progressRecentes.visibility = View.GONE
                recyclerRecentes.visibility = if (recentAdapter.itemCount == 0) View.GONE else View.VISIBLE
                buildIndicators(recentAdapter.itemCount)
                updateIndicatorFromLayout()
                startAutoScroll()
            }
    }

    private fun docParaMapaResumoMaker(doc: DocumentSnapshot, uid: String): MapaResumo {
        return MapaResumo(
            id = doc.id,
            nome = doc.getString("nome") ?: "Mapa sem nome",
            descricao = doc.getString("descricao") ?: "",
            autorUid = uid,
            autorNome = doc.getString("nomeAutor") ?: uid,
            dataCriacao = doc.getTimestamp("dataCriacao"),
            imagemUrl = doc.getString("imagemUrl"),
            imagemBlob = doc.getBlob("imagemBlob"),
            imagemMime = doc.getString("imagemMime"),
            imagemBlobThumb = doc.getBlob("imagemBlobThumb"),
            imagemMimeThumb = doc.getString("imagemMimeThumb")
        )
    }

    private fun buildIndicators(count: Int) {
        indicatorsRecentes.removeAllViews()
        if (count <= 1) {
            indicatorsRecentes.visibility = View.GONE
            return
        }
        indicatorsRecentes.visibility = View.VISIBLE
        val dm = resources.displayMetrics
        val dotMargin = (4 * dm.density).toInt()
        repeat(count) { idx ->
            val iv = ImageView(this)
            iv.setImageResource(if (idx == 0) R.drawable.dot_selected else R.drawable.dot_unselected)
            val lp = LinearLayout.LayoutParams(LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT)
            lp.setMargins(dotMargin, 0, dotMargin, 0)
            iv.layoutParams = lp
            indicatorsRecentes.addView(iv)
        }
    }

    private fun setCurrentIndicator(index: Int) {
        val n = indicatorsRecentes.childCount
        if (index < 0 || index >= n) return
        for (i in 0 until n) {
            val iv = indicatorsRecentes.getChildAt(i) as? ImageView ?: continue
            iv.setImageResource(if (i == index) R.drawable.dot_selected else R.drawable.dot_unselected)
        }
    }

    private fun onMapaClicked(m: MapaResumo) {
        val dialog = com.google.android.material.bottomsheet.BottomSheetDialog(this)
        dialog.setContentView(R.layout.bottomsheet_mapa_preview)

        val txtTitulo = dialog.findViewById<TextView>(R.id.txtTituloMapa)
        val txtDesc = dialog.findViewById<TextView>(R.id.txtDescricaoMapa)
        val ivPreview = dialog.findViewById<ImageView>(R.id.ivPreview)
        val btnIniciar = dialog.findViewById<android.widget.Button>(R.id.btnIniciarNavegacao)
        val btnBaixar = dialog.findViewById<android.widget.Button>(R.id.btnBaixarQRCode)
        val cardDownload = dialog.findViewById<com.google.android.material.card.MaterialCardView>(R.id.cardDownloadQRCode)
        val btnPDF = dialog.findViewById<android.widget.Button>(R.id.btnDownloadPDF)
        val btnPNG = dialog.findViewById<android.widget.Button>(R.id.btnDownloadPNG)

        txtTitulo?.text = m.nome
        txtDesc?.text = m.descricao.ifBlank { "Sem descrição" }

        // Carrega preview (thumb/medium/url)
        if (ivPreview != null) {
            val medium = m.imagemBlob?.toBytes()
            val thumb = m.imagemBlobThumb?.toBytes()
            when {
                medium != null && medium.isNotEmpty() -> {
                    com.bumptech.glide.Glide.with(ivPreview.context)
                        .load(medium)
                        .centerCrop()
                        .placeholder(R.drawable.ic_minimap_placeholder)
                        .error(R.drawable.ic_minimap_placeholder)
                        .into(ivPreview)
                }
                thumb != null && thumb.isNotEmpty() -> {
                    com.bumptech.glide.Glide.with(ivPreview.context)
                        .load(thumb)
                        .centerCrop()
                        .placeholder(R.drawable.ic_minimap_placeholder)
                        .error(R.drawable.ic_minimap_placeholder)
                        .into(ivPreview)
                }
                else -> {
                    val url = m.imagemUrl
                    if (!url.isNullOrBlank()) {
                        if (url.startsWith("gs://")) {
                            val ref = com.google.firebase.storage.FirebaseStorage.getInstance().getReferenceFromUrl(url)
                            ref.downloadUrl
                                .addOnSuccessListener { httpsUri ->
                                    com.bumptech.glide.Glide.with(ivPreview.context)
                                        .load(httpsUri)
                                        .centerCrop()
                                        .placeholder(R.drawable.ic_minimap_placeholder)
                                        .error(R.drawable.ic_minimap_placeholder)
                                        .into(ivPreview)
                                }
                                .addOnFailureListener {
                                    ivPreview.setImageResource(R.drawable.ic_minimap_placeholder)
                                }
                        } else {
                            com.bumptech.glide.Glide.with(ivPreview.context)
                                .load(url)
                                .centerCrop()
                                .placeholder(R.drawable.ic_minimap_placeholder)
                                .error(R.drawable.ic_minimap_placeholder)
                                .into(ivPreview)
                        }
                    } else {
                        ivPreview.setImageResource(R.drawable.ic_minimap_placeholder)
                    }
                }
            }
        }

        btnIniciar?.setOnClickListener {
            dialog.dismiss()
            startActivity(Intent(this, ActivityNavHud::class.java).apply {
                putExtra("MAP_ID", m.id)
            })
        }

        btnBaixar?.setOnClickListener {
            // Substituir os botões principais pelos botões de download
            btnIniciar?.visibility = View.GONE
            btnBaixar.visibility = View.GONE
            cardDownload?.visibility = View.VISIBLE
        }

        btnPNG?.setOnClickListener {
            val ok = saveQrAsPng(m.id)
            android.widget.Toast.makeText(this, if (ok) "QR salvo em Imagens/IndoorAR" else "Falha ao salvar QR", android.widget.Toast.LENGTH_SHORT).show()
        }
        btnPDF?.setOnClickListener {
            val ok = saveQrAsPdf(m.id)
            android.widget.Toast.makeText(this, if (ok) "PDF salvo em Downloads" else "Falha ao salvar PDF", android.widget.Toast.LENGTH_SHORT).show()
        }

        dialog.show()
    }

    private fun generateQrBitmap(content: String, size: Int = 1024): android.graphics.Bitmap? {
        return try {
            val hints = mapOf(
                com.google.zxing.EncodeHintType.ERROR_CORRECTION to com.google.zxing.qrcode.decoder.ErrorCorrectionLevel.M,
                com.google.zxing.EncodeHintType.CHARACTER_SET to "UTF-8",
                com.google.zxing.EncodeHintType.MARGIN to 1
            )
            val bitMatrix = com.google.zxing.qrcode.QRCodeWriter().encode(content, com.google.zxing.BarcodeFormat.QR_CODE, size, size, hints)
            val width = bitMatrix.width
            val height = bitMatrix.height
            val bmp = createBitmap(width, height)
            for (x in 0 until width) {
                for (y in 0 until height) {
                    bmp[x, y] = if (bitMatrix.get(x, y)) android.graphics.Color.BLACK else android.graphics.Color.WHITE
                }
            }
            bmp
        } catch (_: Exception) { null }
    }

    private fun saveQrAsPng(mapId: String): Boolean {
        val bmp = generateQrBitmap(mapId) ?: return false
        return try {
            val filename = "QR_${mapId}_${java.text.SimpleDateFormat("yyyyMMdd_HHmmss", java.util.Locale.getDefault()).format(java.util.Date())}.png"
            val values = android.content.ContentValues().apply {
                put(android.provider.MediaStore.Images.Media.DISPLAY_NAME, filename)
                put(android.provider.MediaStore.Images.Media.MIME_TYPE, "image/png")
                put(android.provider.MediaStore.Images.Media.RELATIVE_PATH, "Pictures/IndoorAR")
                put(android.provider.MediaStore.Images.Media.IS_PENDING, 1)
            }
            val resolver = contentResolver
            val uri = resolver.insert(android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI, values) ?: return false
            resolver.openOutputStream(uri)?.use { out ->
                bmp.compress(android.graphics.Bitmap.CompressFormat.PNG, 100, out)
            } ?: return false
            values.clear(); values.put(android.provider.MediaStore.Images.Media.IS_PENDING, 0)
            resolver.update(uri, values, null, null)
            true
        } catch (_: Exception) { false }
    }

    private fun saveQrAsPdf(mapId: String): Boolean {
        return try {
            val bmp = generateQrBitmap(mapId, 1024) ?: return false
            val filename = "QR_${mapId}_${java.text.SimpleDateFormat("yyyyMMdd_HHmmss", java.util.Locale.getDefault()).format(java.util.Date())}.pdf"
            val values = android.content.ContentValues().apply {
                put(android.provider.MediaStore.Downloads.DISPLAY_NAME, filename)
                put(android.provider.MediaStore.Downloads.MIME_TYPE, "application/pdf")
                put(android.provider.MediaStore.Downloads.IS_PENDING, 1)
            }
            val resolver = contentResolver
            val collection = android.provider.MediaStore.Downloads.getContentUri(android.provider.MediaStore.VOLUME_EXTERNAL_PRIMARY)
            val uri: android.net.Uri = resolver.insert(collection, values) ?: return false
            resolver.openOutputStream(uri)?.use { out ->
                writeSimplePdfWithBitmap(bmp, out)
            } ?: return false
            values.clear(); values.put(android.provider.MediaStore.Downloads.IS_PENDING, 0)
            resolver.update(uri, values, null, null)
            true
        } catch (_: Exception) { false }
    }

    private fun writeSimplePdfWithBitmap(bmp: android.graphics.Bitmap, out: java.io.OutputStream) {
        val pageWidth = 595 // A4 width at 72dpi (~8.27in * 72)
        val pageHeight = 842 // A4 height at 72dpi (~11.69in * 72)
        val scale =
            kotlin.math.min(pageWidth.toFloat() / bmp.width, pageHeight.toFloat() / bmp.height)
        val scaled = bmp.scale((bmp.width * scale).toInt(), (bmp.height * scale).toInt())
        val document = android.graphics.pdf.PdfDocument()
        val pageInfo = android.graphics.pdf.PdfDocument.PageInfo.Builder(pageWidth, pageHeight, 1).create()
        val page = document.startPage(pageInfo)
        val canvas = page.canvas
        val left = (pageWidth - scaled.width) / 2f
        val top = (pageHeight - scaled.height) / 2f
        canvas.drawColor(android.graphics.Color.WHITE)
        canvas.drawBitmap(scaled, left, top, null)
        document.finishPage(page)
        document.writeTo(out)
        document.close()
        if (!scaled.isRecycled) scaled.recycle()
    }
}

package com.example.indoorar

import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.util.Log
import android.widget.ImageView
import android.widget.LinearLayout
import androidx.activity.enableEdgeToEdge
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AlertDialog
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import com.bumptech.glide.request.RequestOptions
import com.google.firebase.auth.FirebaseAuth
import java.io.File
import java.io.FileOutputStream
import java.io.InputStream
import androidx.core.net.toUri
import androidx.core.content.edit
import com.yalantis.ucrop.UCrop
import androidx.core.content.FileProvider

class ActivityPerfilComum : BaseActivity() {
    companion object {
        private const val prefsName = "perfil_prefs"
        private const val keyImageUri = "image_uri"
        private const val keyImagePath = "image_path"
    }

    private lateinit var userImage: ImageView

    // Helper to (re)configure the BottomNavigationView listener consistently
    // Helper to (re)configure the BottomNavigationView listener consistently
    private fun setupBottomNav(bottomNav: com.google.android.material.bottomnavigation.BottomNavigationView) {
        bottomNav.setOnItemSelectedListener { item ->
            try {
                when (item.itemId) {
                    R.id.action_home -> { startActivity(Intent(this, ActivityHomeComum::class.java)); true }
                    R.id.action_scan -> { startActivity(Intent(this, ActivityScanQR::class.java)); true }
                    R.id.action_favoritos -> { startActivity(Intent(this, ActivityFavoritos::class.java)); true }
                    R.id.action_config -> { /* already here */ true }
                    R.id.action_criar -> { startActivity(Intent(this, com.example.indoorar.ui.ActivityEditor::class.java)); true }
                    R.id.action_estatisticas -> { startActivity(Intent(this, ActivityEstatisticas::class.java)); true }
                    else -> false
                }
            } catch (e: Exception) {
                Log.e("PerfilComum", "Erro ao tratar seleção do bottom nav", e)
                false
            }
        }
        // Select profile item after listener is set
        bottomNav.post { try { bottomNav.selectedItemId = R.id.action_config } catch (_: Exception) {} }
    }

    private fun saveImageToInternalStorage(uri: Uri): String? {
        return try {
            val inputStream: InputStream? = contentResolver.openInputStream(uri)
            val file = File(filesDir, "profile_image.jpg")
            val outputStream = FileOutputStream(file)
            inputStream?.copyTo(outputStream)
            inputStream?.close()
            outputStream.close()
            file.absolutePath
        } catch (e: Exception) {
            Log.e("PerfilComum", "Erro ao salvar imagem", e)
            null
        }
    }

    private val cropImageLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->
        val data = result.data
        if (result.resultCode == RESULT_OK && data != null) {
            val resultUri = UCrop.getOutput(data)
            if (resultUri != null) {
                val imagePath = saveImageToInternalStorage(resultUri)
                if (imagePath != null) {
                    com.bumptech.glide.Glide.with(this)
                        .load(imagePath)
                        .apply(RequestOptions.circleCropTransform())
                        .placeholder(R.drawable.account_circle)
                        .error(R.drawable.account_circle)
                        .into(userImage)
                    val prefs = getSharedPreferences(prefsName, MODE_PRIVATE)
                    prefs.edit { putString(keyImagePath, imagePath).remove(keyImageUri) }
                } else {
                    userImage.setImageResource(R.drawable.account_circle)
                }
            } else {
                val err = UCrop.getError(data)
                if (err != null) Log.e("PerfilComum", "UCrop error", err)
                userImage.setImageResource(R.drawable.account_circle)
            }
        } else if (result.data != null) {
            val err = UCrop.getError(result.data!!)
            if (err != null) Log.e("PerfilComum", "UCrop RESULT_ERROR", err)
        }
    }

    private val pickImageLauncher = registerForActivityResult(ActivityResultContracts.GetContent()) { uri: Uri? ->
        uri?.let {
            try {
                val destinationFile = File(getExternalFilesDir(null), "cropped_profile_image.jpg")
                val destinationUri = FileProvider.getUriForFile(
                    this,
                    "$packageName.fileprovider",
                    destinationFile
                )
                val uCrop = UCrop.of(it, destinationUri)
                    .withAspectRatio(1f, 1f)
                    .withOptions(UCrop.Options().apply {
                        setCircleDimmedLayer(true)
                        setShowCropFrame(false)
                        setShowCropGrid(false)
                    })
                val intent = uCrop.getIntent(this).apply {
                    addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION)
                }
                val targetPkg = intent.component?.packageName
                    ?: intent.resolveActivity(packageManager)?.packageName
                if (!targetPkg.isNullOrBlank()) {
                    try { grantUriPermission(targetPkg, it, Intent.FLAG_GRANT_READ_URI_PERMISSION) } catch (_: Exception) {}
                    try { grantUriPermission(targetPkg, destinationUri, Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION) } catch (_: Exception) {}
                }
                cropImageLauncher.launch(intent)
            } catch (e: Exception) {
                Log.e("PerfilComum", "Falha ao abrir UCrop, aplicando fallback", e)
                try {
                    val imagePath = saveImageToInternalStorage(it)
                    if (imagePath != null) {
                        com.bumptech.glide.Glide.with(this)
                            .load(imagePath)
                            .apply(RequestOptions.circleCropTransform())
                            .placeholder(R.drawable.account_circle)
                            .error(R.drawable.account_circle)
                            .into(userImage)
                        val prefs = getSharedPreferences(prefsName, MODE_PRIVATE)
                        prefs.edit { putString(keyImagePath, imagePath).remove(keyImageUri) }
                    } else {
                        userImage.setImageResource(R.drawable.account_circle)
                    }
                } catch (_: Exception) {
                    android.widget.Toast.makeText(this, "Erro ao processar imagem selecionada", android.widget.Toast.LENGTH_LONG).show()
                }
            }
        }
    }

    private val requestMediaImagesPermissionLauncher = registerForActivityResult(ActivityResultContracts.RequestPermission()) { isGranted ->
        if (isGranted) pickImageLauncher.launch("image/*")
        else android.widget.Toast.makeText(this, "Permissão para acessar imagens negada", android.widget.Toast.LENGTH_LONG).show()
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        // Use the existing perfil_comum layout (it contains the expected IDs) and then swap the menu to maker
        setContentView(R.layout.activity_perfil_comum)
        setContentView(R.layout.activity_perfil_comum)
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)
            insets
        }

        val txtNomeUsuario = findViewById<android.widget.TextView>(R.id.txtNomeUsuario)
        val txtEmailUsuario = findViewById<android.widget.TextView>(R.id.txtEmailUsuario)
        userImage = findViewById(R.id.userImage)
        val prefs = getSharedPreferences(prefsName, MODE_PRIVATE)
        val savedPath = prefs.getString(keyImagePath, null)
        val savedUri = prefs.getString(keyImageUri, null)
        val user = FirebaseAuth.getInstance().currentUser
        if (user != null) {
            txtEmailUsuario.text = user.email ?: "Email não disponível"
            val db = com.google.firebase.firestore.FirebaseFirestore.getInstance()
            db.collection("usuarios").document(user.uid).get().addOnSuccessListener { doc ->
                val nome = doc.getString("nome") ?: "Nome não disponível"
                txtNomeUsuario.text = nome
            }.addOnFailureListener {
                txtNomeUsuario.text = "Nome não disponível"
            }
        } else {
            txtNomeUsuario.text = "Usuário não logado"
            txtEmailUsuario.text = "Usuário não logado"
        }

        if (savedPath != null) {
            Log.d("PerfilComum", "Carregando imagem do caminho: $savedPath")
            com.bumptech.glide.Glide.with(this)
                .load(savedPath)
                .apply(RequestOptions.circleCropTransform())
                .placeholder(R.drawable.account_circle)
                .error(R.drawable.account_circle)
                .into(userImage)
        } else if (savedUri != null) {
            try {
                Log.d("PerfilComum", "Tentando carregar imagem URI: $savedUri")
                com.bumptech.glide.Glide.with(this)
                    .load(savedUri.toUri())
                    .apply(RequestOptions.circleCropTransform())
                    .placeholder(R.drawable.account_circle)
                    .error(R.drawable.account_circle)
                    .into(userImage)
            } catch (_: Exception) {
                userImage.setImageResource(R.drawable.account_circle)
            }
        } else {
            userImage.setImageResource(R.drawable.account_circle)
        }

        userImage.setOnClickListener {
            val options = arrayOf("Remover foto de perfil", "Escolher da galeria")
            AlertDialog.Builder(this)
                .setTitle("Foto de perfil")
                .setItems(options) { dialog, which ->
                    when (which) {
                        0 -> {
                            val prefs = getSharedPreferences(prefsName, MODE_PRIVATE)
                            prefs.edit { remove(keyImagePath).remove(keyImageUri) }
                            userImage.setImageResource(R.drawable.account_circle)
                        }
                        1 -> {
                            if (android.os.Build.VERSION.SDK_INT >= 33) {
                                requestMediaImagesPermissionLauncher.launch(android.Manifest.permission.READ_MEDIA_IMAGES)
                            } else {
                                pickImageLauncher.launch("image/*")
                            }
                        }
                    }
                }
                .show()
        }

        val itemSair = findViewById<LinearLayout>(R.id.itemSair)
        itemSair.setOnClickListener {
            FirebaseAuth.getInstance().signOut()
            val intent = Intent(this, ActivityLogin::class.java)
            intent.flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
            startActivity(intent)
            finish()
        }

        val itemConfiguracoes = findViewById<LinearLayout>(R.id.itemConfiguracoes)
        itemConfiguracoes?.setOnClickListener {
            startActivity(Intent(this, ActivityConfigConta::class.java))
        }
        val itemHistorico = findViewById<LinearLayout>(R.id.itemHistorico)
        itemHistorico?.setOnClickListener {
            android.widget.Toast.makeText(this, "Histórico - em desenvolvimento", android.widget.Toast.LENGTH_SHORT).show()
        }
        val itemCalendario = findViewById<LinearLayout>(R.id.itemCalendario)
        itemCalendario?.setOnClickListener {
            android.widget.Toast.makeText(this, "Estatísticas - em desenvolvimento", android.widget.Toast.LENGTH_SHORT).show()
        }
        val itemAjuda = findViewById<LinearLayout>(R.id.itemAjuda)
        itemAjuda?.setOnClickListener {
            android.widget.Toast.makeText(this, "Ajuda e Suporte - em desenvolvimento", android.widget.Toast.LENGTH_SHORT).show()
        }

        val bottomNav = findViewById<com.google.android.material.bottomnavigation.BottomNavigationView>(R.id.bottomNavPerfil)
        if (bottomNav != null) {
            bottomNav.menu.clear()
            bottomNav.inflateMenu(R.menu.bottom_nav_comum)
            setupBottomNav(bottomNav)
        }
    }

    override fun onResume() {
        super.onResume()
        syncUserEmailToFirestore {
            val user = FirebaseAuth.getInstance().currentUser
            val emailAtual = user?.email ?: "Email não disponível"
            findViewById<android.widget.TextView>(R.id.txtEmailUsuario)?.text = emailAtual
        }
    }
}

